// Frontend reading a Response Body
async function getWeather() {
  // 1. Make the request
  const response = await fetch('https://api.com/weather');

  // 2. We have the network response, but we need to extract the Body.
  // This reads the raw stream of text and parses it into a JS Object.
  const data = await response.json();

  console.log(data.temp); // 72
}

// Backend sending a Response Body (Express.js)
app.get('/weather', (req, res) => {
  const myData = { temp: 72, status: "Sunny" };

  // res.json() automatically converts the JS object to a string
  // and automatically sets the 'Content-Type: application/json' header!
  res.status(200).json(myData);
});
